# Smart Retail Demand Forecasting & Dynamic Pricing System
# Streamlit dashboard connected to the CSV outputs generated by the notebook.

from pathlib import Path
import pandas as pd
import streamlit as st
import plotly.express as px

# -----------------------------
# Page configuration
# -----------------------------
st.set_page_config(
    page_title="Smart Retail Dashboard",
    page_icon="🛒",
    layout="wide"
)

BASE_DIR = Path(__file__).resolve().parent

FILES = {
    "forecast": "future_demand_forecast.csv",
    "pricing": "retail_pricing_recommendations.csv",
    "recommendations": "final_business_recommendations.csv",
    "revenue": "revenue_impact_summary.csv",
    "model": "model_comparison_results.csv",
    "test": "demand_forecast_results.csv",
    "inventory": "inventory_availability_used.csv",
}

# -----------------------------
# Load exported notebook outputs
# -----------------------------
@st.cache_data
def load_csv(file_path):
    path = BASE_DIR / file_path
    if path.exists():
        return pd.read_csv(path)
    return pd.DataFrame()


@st.cache_data
def load_all_data():
    data = {}
    for key, filename in FILES.items():
        data[key] = load_csv(filename)

    # Convert date columns when they are available.
    for key, frame in data.items():
        if not frame.empty and "date" in frame.columns:
            frame["date"] = pd.to_datetime(frame["date"], errors="coerce")
            data[key] = frame

    return data


data = load_all_data()

forecast = data["forecast"]
pricing = data["pricing"]
recommendations = data["recommendations"]
revenue = data["revenue"]
model_results = data["model"]
test_results = data["test"]
inventory = data["inventory"]

# -----------------------------
# Common helper functions
# -----------------------------
def money(value):
    if pd.isna(value):
        return "N/A"
    return f"₹{value:,.2f}"


def show_missing_files():
    missing = [
        filename for key, filename in FILES.items()
        if data[key].empty
    ]
    if missing:
        st.warning(
            "Some notebook output files are missing. Run all cells of the "
            "Jupyter notebook first, then keep the exported CSV files in "
            "the same folder as app.py."
        )
        with st.expander("Required / expected output files"):
            for filename in missing:
                st.write(f"• {filename}")


def apply_filters(frame):
    if frame.empty:
        return frame

    filtered = frame.copy()
